    const overusedList = ['suddenly', 'really', 'just', 'felt', 'began', 'stood', 'looked', 'very', 'seemed', 'turned'];
    const overusedCounts = {};
    overusedList.forEach(w => {
      const reg = new RegExp(`\\b${w}\\b`, 'gi');
